// Fake Cloudinary upload API (:5098) and fake ai-service (:5097) for the live integration tests.
import http from "node:http";
import https from "node:https";
import fs from "node:fs";
import { fileURLToPath } from "node:url";

// The Cloudinary SDK only speaks HTTPS, so the fake Cloudinary uses a throwaway self-signed cert
// (generated by make-cert.mjs into the git-ignored certs/ folder; CN=127.0.0.1). Start the server under test with NODE_EXTRA_CA_CERTS pointing at it.
const cert = (f) => {
  const file = fileURLToPath(new URL(`./certs/${f}`, import.meta.url));
  if (!fs.existsSync(file)) throw new Error("Missing test certificate: run `node tests/integration/make-cert.mjs` first");
  return fs.readFileSync(file);
};

const listen = (server, port) => new Promise((resolve) => server.listen(port, "127.0.0.1", resolve));
const readBody = (req) =>
  new Promise((resolve) => {
    const chunks = [];
    req.on("data", (c) => chunks.push(c));
    req.on("end", () => resolve(Buffer.concat(chunks)));
  });

export async function startStubs({ cloudinaryPort = 5098, aiPort = 5097 } = {}) {
  const state = { uploads: [], aiCalls: [], aiMode: "ok", close: null };

  const cloudinary = https.createServer({ key: cert("stub-key.pem"), cert: cert("stub-cert.pem") }, async (req, res) => {
    const body = (await readBody(req)).toString("latin1");
    // multipart: pull the `type` and `folder` fields out so tests can assert how we upload
    const field = (name) => new RegExp(`name="${name}"\\r\\n\\r\\n([^\\r]*)`).exec(body)?.[1];
    const m = /\/v1_1\/([^/]+)\/(raw|image)\/upload/.exec(req.url);
    if (!m) { res.writeHead(404).end(); return; }
    const id = `healthcare-documents/stub_${state.uploads.length + 1}`;
    state.uploads.push({ type: field("type"), folder: field("folder"), resourceType: m[2] });
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({
      public_id: id,
      resource_type: m[2],
      type: field("type") || "upload",
      secure_url: `https://res.cloudinary.com/${m[1]}/${m[2]}/${field("type") || "upload"}/v1/${id}`,
    }));
  });

  const ai = http.createServer(async (req, res) => {
    const raw = (await readBody(req)).toString();
    let body = {};
    try { body = JSON.parse(raw); } catch { /* ignore */ }
    state.aiCalls.push({ path: req.url, auth: req.headers.authorization, body });
    const json = (code, obj) => { res.writeHead(code, { "Content-Type": "application/json" }); res.end(JSON.stringify(obj)); };
    if (state.aiMode === "fail") return json(502, { detail: "stub failure" });
    if (req.url === "/summarize") {
      return json(200, {
        documentType: "Lab Report",
        keyInfo: "Stub summary of the uploaded document.",
        abnormalValues: null,
        followUp: "Discuss with your doctor",
        disclaimer: "This summary is for informational purposes only and is not medical advice.",
      });
    }
    if (req.url === "/assistant/query") {
      return json(200, { filters: { specialization: "Cardiologist", location: "Pune", maxFee: 500 } });
    }
    json(404, {});
  });

  await Promise.all([listen(cloudinary, cloudinaryPort), listen(ai, aiPort)]);
  state.close = () => Promise.all([new Promise((r) => cloudinary.close(r)), new Promise((r) => ai.close(r))]);
  return state;
}
